module.render:
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const numArg = (v, d) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
const NAME = '[\\p{L}\\p{N}_.-]+';
const LABEL_RE = new RegExp('^#(' + NAME + ')((?:\\s+[^\\s:]+)*)\\s*:\\s*([\\s\\S]*)$', 'u');

// ---- the body: formula text, label lines, legend lines --------------------
const labels = [];
const legend = [];
const formulaLines = [];
// Section 1 is the formula (a `#name: …` line there is still a label); the later
// sections hold labels and legend items.
const takeLine = (line, inFormula) => {
  const t = line.trim();
  if (!t) { if (inFormula) formulaLines.push(line); return; }
  const lm = LABEL_RE.exec(t);
  if (lm) { labels.push({ name: lm[1], opts: lm[2].trim().split(/\s+/).filter(Boolean), text: lm[3].trim() }); return; }
  if (inFormula) { formulaLines.push(line); return; }
  legend.push(t.replace(/^[-*+]\s+/, ''));
};
String(sections[0] || '').split(/\r?\n/).forEach((l) => takeLine(l, true));
sections.slice(1).forEach((sec) => String(sec || '').split(/\r?\n/).forEach((l) => takeLine(l, false)));

let tex = formulaLines.join('\n').trim();
// Forgive delimiters / an environment written around it out of habit.
const unwrap = [/^\\\[([\s\S]*)\\\]$/, /^\$\$([\s\S]*)\$\$$/, /^\\\(([\s\S]*)\\\)$/,
  /^\\begin\{(?:aligned|align\*?|alignat\*?\{\d+\}|gathered|gather\*?|split|equation\*?|eqnarray\*?)\}([\s\S]*)\\end\{(?:aligned|align\*?|alignat\*?|gathered|gather\*?|split|equation\*?|eqnarray\*?)\}$/];
for (let k = 0; k < 3; k++) {
  let changed = false;
  for (const re of unwrap) { const m = re.exec(tex.trim()); if (m) { tex = m[1].trim(); changed = true; } }
  if (!changed) break;
}

// ---- a small TeX scanner: tokens with their nesting --------------------------
const tokenize = (s) => {
  const out = [];
  let i = 0;
  while (i < s.length) {
    const c = s[i];
    if (c === '\\') {
      const m = /^\\([A-Za-z]+)/.exec(s.slice(i));
      if (m) { out.push({ t: 'cmd', v: m[1], a: i, b: i + m[0].length }); i += m[0].length; continue; }
      out.push({ t: 'esc', v: s[i + 1] || '', a: i, b: Math.min(s.length, i + 2) }); i += 2; continue;
    }
    if (c === '%') { const e = s.indexOf('\n', i); const end = e < 0 ? s.length : e; out.push({ t: 'cmt', v: '', a: i, b: end }); i = end; continue; }
    out.push({ t: 'ch', v: c, a: i, b: i + 1 }); i++;
  }
  return out;
};
const OPENS = new Set(['langle', 'lvert', 'lVert', 'lceil', 'lfloor', 'lbrace', 'lbrack']);
const CLOSES = new Set(['rangle', 'rvert', 'rVert', 'rceil', 'rfloor', 'rbrace', 'rbrack']);
// Each token with the depth it sits at: g = braces + environments + \left…\right
// (where & and \\ do not belong to the rows), p = parentheses / brackets as well.
const scan = (s) => {
  const toks = tokenize(s);
  let brace = 0, env = 0, lr = 0, paren = 0, skipDelim = false;
  for (const tk of toks) {
    tk.g = brace + env + lr;
    tk.p = tk.g + paren;
    // The delimiter after \left / \right (( [ \{ \langle . |) is no bracket of its own.
    if (skipDelim) {
      if (tk.t === 'ch' && /\s/.test(tk.v)) continue;
      skipDelim = false;
      if (tk.t !== 'ch' || tk.v !== '{') continue;
    }
    if (tk.t === 'ch') {
      if (tk.v === '{') brace++;
      else if (tk.v === '}') brace = Math.max(0, brace - 1);
      else if (tk.v === '(' || tk.v === '[') paren++;
      else if (tk.v === ')' || tk.v === ']') paren = Math.max(0, paren - 1);
    } else if (tk.t === 'cmd') {
      if (tk.v === 'begin') env++;
      else if (tk.v === 'end') env = Math.max(0, env - 1);
      else if (tk.v === 'left') { lr++; skipDelim = true; }
      else if (tk.v === 'right') { lr = Math.max(0, lr - 1); skipDelim = true; }
      else if (OPENS.has(tk.v)) paren++;
      else if (CLOSES.has(tk.v)) paren = Math.max(0, paren - 1);
    } else if (tk.t === 'esc') {
      if (tk.v === '{') paren++;
      else if (tk.v === '}') paren = Math.max(0, paren - 1);
    }
  }
  return toks;
};

// ---- rows ------------------------------------------------------------------
const splitAt = (s, cuts) => { const out = []; let last = 0; for (const [a, b] of cuts) { out.push(s.slice(last, a)); last = b; } out.push(s.slice(last)); return out; };
let rowTexts;
{
  const toks = scan(tex);
  const breaks = toks.filter((t) => t.g === 0 && t.t === 'esc' && t.v === '\\').map((t) => [t.a, t.b]);
  // `\\[4pt]`: the spacing after a row break is dropped with it.
  if (breaks.length) rowTexts = splitAt(tex, breaks).map((r, k) => (k > 0 ? r.replace(/^\s*\[[^\]\n]*\]/, '') : r));
  else rowTexts = splitAt(tex, toks.filter((t) => t.g === 0 && t.t === 'ch' && t.v === '\n').map((t) => [t.a, t.b]));
}
rowTexts = rowTexts.map((r) => r.trim()).filter((r) => r !== '');

const RELS = new Set(['le', 'leq', 'ge', 'geq', 'ne', 'neq', 'approx', 'approxeq', 'simeq', 'sim', 'equiv', 'propto', 'lt', 'gt',
  'leqq', 'geqq', 'leqslant', 'geqslant', 'lesssim', 'gtrsim', 'll', 'gg', 'iff', 'implies', 'impliedby', 'Rightarrow', 'Leftarrow',
  'Leftrightarrow', 'Longrightarrow', 'Longleftarrow', 'Longleftrightarrow', 'coloneqq', 'eqqcolon', 'doteq', 'cong', 'prec', 'succ', 'preceq', 'succeq']);
const RELCH = '=<>≤≥≠≈≡≃∼∝⇔⇒⇐≪≫≅';
const isRel = (t) => (t.t === 'ch' && RELCH.indexOf(t.v) >= 0) || (t.t === 'cmd' && RELS.has(t.v));

const rows = rowTexts.map((rt) => {
  const toks = scan(rt);
  let note = '';
  let body = rt;
  for (let k = 0; k + 1 < toks.length; k++) {
    const t = toks[k];
    if (t.g === 0 && t.t === 'ch' && t.v === '&' && toks[k + 1].t === 'ch' && toks[k + 1].v === '&' && toks[k + 1].a === t.b) {
      note = rt.slice(toks[k + 1].b).trim();
      body = rt.slice(0, t.a);
      break;
    }
  }
  const btoks = scan(body);
  const amps = btoks.filter((t) => t.g === 0 && t.t === 'ch' && t.v === '&');
  let left = null, right = null;
  if (amps.length) {
    left = body.slice(0, amps[0].a);
    right = splitAt(body.slice(amps[0].b), amps.slice(1).map((t) => [t.a - amps[0].b, t.b - amps[0].b])).join(' ');
  }
  return { body: body.trim(), left, right, note, hasAmp: amps.length > 0 };
});
const anyAmp = rows.some((r) => r.hasAmp);
rows.forEach((r) => {
  if (anyAmp) {
    if (!r.hasAmp) { r.left = ''; r.right = r.body; }
    return;
  }
  // No & anywhere: line the rows up at their first relation.
  const toks = scan(r.body);
  let at = toks.find((t) => t.p === 0 && isRel(t));
  if (!at) at = toks.find((t) => t.g === 0 && isRel(t));
  if (!at) { r.left = ''; r.right = r.body; return; }
  let a = at.a;
  const before = r.body.slice(0, a).replace(/\s+$/, '');
  if (/:$/.test(before)) a = before.length - 1;
  r.left = r.body.slice(0, a);
  r.right = r.body.slice(a);
});

// A row's note may have been written the LaTeX way: \text{…}, \quad\text{…}.
const noteText = (n) => {
  let s = n.trim();
  for (let k = 0; k < 3; k++) {
    const m = /^(?:\\(?:quad|qquad|;|,|:)\s*)*\\(?:text|textrm|mbox|textnormal)\{([\s\S]*)\}\s*$/.exec(s);
    if (!m) break;
    s = m[1].trim();
  }
  return s;
};

// ---- labels: wrap each named part with its brace and room for the label -----
const sigSrc = JSON.stringify([tex, labels, legend, args]);
let h = 0;
for (let i = 0; i < sigSrc.length; i++) h = (h * 31 + sigSrc.charCodeAt(i)) | 0;
const scope = 'mdp-xpl-' + Math.abs(h).toString(36);
const lsize = 1;
const placed = new Set();
const anchorOf = new Map();
labels.forEach((L, i) => {
  L.side = L.opts.some((o) => /^(above|over|top)$/i.test(o)) ? 'above' : 'below';
  const lv = L.opts.find((o) => /^[1-4]$/.test(o));
  L.level = lv ? Number(lv) : 1;
  L.align = L.opts.some((o) => /^(left|start)$/i.test(o)) ? 's' : L.opts.some((o) => /^(right|end)$/i.test(o)) ? 'e' : 'c';
  L.style = L.opts.some((o) => /^plain$/i.test(o)) ? 'plain' : L.opts.some((o) => /^line$/i.test(o)) ? 'line' : 'brace';
  const st = L.opts.map((o) => /^step=(\d+)$/i.exec(o)).find(Boolean);
  L.step = st ? Number(st[1]) : 0;
  const col = L.opts.map((o) => /^colou?r=(.+)$/i.exec(o)).find(Boolean);
  L.color = col ? col[1].replace(/[;"<>{}]/g, '') : '';
  L.anchor = '--' + scope + '-' + i;
  if (!anchorOf.has(L.name)) anchorOf.set(L.name, L);
});
// `\focus{name}{X}` of a labelled name → `\focus{name}{\underbrace{X}_{<room>}}`:
// KaTeX draws the brace and leaves room under it, the label is laid over that room
// (it takes no width, so the formula is not pushed apart). `here` collects the
// names placed in this piece (a label is drawn in the row its part is in).
const FOCUS_OPEN = new RegExp('\\\\focus\\{(' + NAME + ')\\}\\{', 'u');
const wrapParts = (s, here) => {
  let out = '';
  let rest = s;
  for (;;) {
    const m = FOCUS_OPEN.exec(rest);
    if (!m) return out + rest;
    let depth = 1;
    let i = m.index + m[0].length;
    for (; i < rest.length; i++) {
      const c = rest[i];
      if (c === '\\') { i++; continue; }
      if (c === '{') depth++;
      else if (c === '}' && --depth === 0) break;
    }
    if (depth !== 0) return out + rest;
    const inner = wrapParts(rest.slice(m.index + m[0].length, i), here);
    const L = anchorOf.get(m[1]);
    let wrapped = inner;
    if (L && !placed.has(m[1])) {
      // The room under the brace (or the part), in LABEL em: the label's line
      // (1.25) + 0.2, one more line per level, and for a `line` the line itself.
      // KaTeX sizes a \rule in the formula's em (1/0.7 label em) and keeps 0.2 of
      // it between the brace and the room — measured in the browser.
      const reserve = (L.style === 'line' ? 2.2 : 1.45) + (L.level - 1) * 1.3;
      const room = ((reserve * 0.7 - 0.2) * lsize).toFixed(3);
      const strut = '\\rule{0pt}{' + room + 'em}';
      if (L.style === 'brace') wrapped = L.side === 'above' ? '\\overbrace{' + inner + '}^{' + strut + '}' : '\\underbrace{' + inner + '}_{' + strut + '}';
      else wrapped = L.side === 'above' ? '\\overset{' + strut + '}{' + inner + '}' : '\\underset{' + strut + '}{' + inner + '}';
      placed.add(m[1]);
      here.push(L);
    }
    out += rest.slice(0, m.index) + m[0] + wrapped + '}';
    rest = rest.slice(i + 1);
  }
};

// ---- output ------------------------------------------------------------------
const from = Math.max(1, Math.round(numArg(args.from, 1)));
const steps = String(args.steps || 'none').toLowerCase();
const notesBelow = String(args.notes || 'right').toLowerCase() === 'below';
const hasNotes = rows.some((r) => r.note);
const prefix = String(args.rows || '').trim().replace(/[^\p{L}\p{N}_.-]/gu, '');
const size = Math.max(0.3, Math.min(3, numArg(args.size, 1)));
const align = String(args.align || 'center').toLowerCase() === 'left' ? 'left' : 'center';
const noteColor = String(args.notecolor || 'var(--muted-color, #5a5a5a)').replace(/[;"<>{}]/g, '');
const labelColor = String(args.labelcolor || '').replace(/[;"<>{}]/g, '');
const math = (s) => '\\(\\displaystyle ' + s + '\\)';
// A row piece that starts with a relation (= …, := …) gets `{}` before it, as in
// `aligned`, so the relation is spaced as one.
const relStart = (s) => {
  const toks = scan(s.trim()).filter((x) => x.t !== 'cmt' && !(x.t === 'ch' && /\s/.test(x.v)));
  if (!toks.length) return false;
  return isRel(toks[0]) || (toks[0].t === 'ch' && toks[0].v === ':' && !!toks[1] && isRel(toks[1]));
};

const labelHtml = (L) => {
  const cls = 'mdp-xpl-lbl mdp-xpl-' + L.side + ' mdp-xpl-' + L.align + ' mdp-xpl-' + L.style + ' mdp-xpl-lv' + L.level;
  const style = 'position-anchor:' + L.anchor + ';' + (L.color ? 'color:' + L.color + ';' : '');
  let html = '<div class="' + cls + '" style="' + style + '">\n\n' + L.text + '\n\n</div>\n';
  if (L.style === 'line' || L.level > 1) html += '<div class="mdp-xpl-stem mdp-xpl-' + L.side + ' mdp-xpl-lv' + L.level + (L.style === 'line' ? ' mdp-xpl-line' : '') + '" style="position-anchor:' + L.anchor + ';' + (L.color ? 'color:' + L.color + ';' : '') + '"></div>\n';
  if (L.step > 0) html = '\n<!-- @build step: ' + L.step + ' -->\n\n' + html + '\n<!-- @endbuild -->\n';
  return html;
};

let body = '';
rows.forEach((r, k) => {
  const rowLabels = [];
  const left = wrapParts(r.left || '', rowLabels);
  let right = wrapParts(r.right || '', rowLabels);
  if (right && relStart(right)) right = '{}' + right;
  const name = prefix ? ' data-mdp-focus="' + esc(prefix + (k + 1)) + '"' : '';
  let row = '<div class="mdp-xpl-row"' + name + '>\n';
  row += '<div class="mdp-xpl-l">\n\n' + (left.trim() ? math(left) : '') + '\n\n</div>\n';
  row += '<div class="mdp-xpl-r">\n\n' + (right.trim() ? math(right) : '') + '\n\n</div>\n';
  if (hasNotes) {
    const nt = r.note ? noteText(r.note) : '';
    let inner = nt;
    if (nt && steps === 'notes') inner = '<!-- @build step: ' + (from + k) + ' -->\n\n' + nt + '\n\n<!-- @endbuild -->';
    row += '<div class="mdp-xpl-n">\n\n' + inner + '\n\n</div>\n';
  }
  rowLabels.forEach((L) => { row += labelHtml(L); });
  row += '</div>\n';
  const st = steps === 'rows' ? (k === 0 ? 0 : from + k - 1) : steps === 'all' ? from + k : 0;
  body += st > 0 ? '\n<!-- @build step: ' + st + ' -->\n\n' + row + '\n<!-- @endbuild -->\n' : row;
});

const missing = labels.filter((L) => anchorOf.get(L.name) === L && !placed.has(L.name));
let css = '';
labels.forEach((L) => {
  if (anchorOf.get(L.name) !== L || !placed.has(L.name)) return;
  css += '.' + scope + ' [data-mdp-focus="' + L.name + '"] { anchor-name: ' + L.anchor + '; display: inline-block; }\n';
});

const cls = 'mdp-mod-explain ' + scope + ' mdp-xpl-' + align + (hasNotes ? ' mdp-xpl-has-notes' : '') + (notesBelow ? ' mdp-xpl-notes-below' : '');
const style = 'font-size:' + size + 'em; --xpl-note:' + noteColor + ';' + (labelColor ? ' --xpl-label:' + labelColor + ';' : '');
let html = '\n\n' + (css ? '<style>' + css + '</style>\n\n' : '');
html += '<div class="' + cls + '" style="' + style + '">\n';
html += '<div class="mdp-xpl-grid">\n' + body + '</div>\n';
if (legend.length || missing.length) {
  html += '<div class="mdp-xpl-legend">\n';
  legend.forEach((it) => { html += '<div class="mdp-xpl-item">\n\n' + it + '\n\n</div>\n'; });
  missing.forEach((L) => { html += '<div class="mdp-xpl-item mdp-xpl-missing" title="no \\focus{' + esc(L.name) + '}{…} in the formula">\n\n#' + esc(L.name) + ': ' + L.text + '\n\n</div>\n'; });
  html += '</div>\n';
}
html += '</div>\n\n';
return html;
